var gSearchAbViewListener = {
  onSelectionChanged() {
    UpdateCardView();
  },
  onCountChanged(aTotal) {
    if (aTotal == 0) {
      document.l10n.setAttributes(
        gStatusText,
        "ab-search-dialog-no-matches-found"
      );
    } else if (aTotal) {
      document.l10n.setAttributes(
        gStatusText,
        "ab-search-dialog-matches-found",
        {
          count: aTotal,
        }
      );
    }
  },
};
